insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2026-may-28th-meet-and-greet-happy-hour', 'May 28th Meet and Greet Happy Hour', 'This May the Chapter hosted a happy hour to welcome new Brothers form the area to come out and see what the Chapter was about. We had the pleasure of reconnecting with a Case Western Alumnus, along with meeting two recent grads from the Ohio State Chapter. We hope to continue to see them along with more of the Northeast Ohio Alumni', 2026, 5, 28, 'f002fe_e647c773ba8b488aae1145d72eac5fce-mv2.jpg', 'Meet & Greet Happy Hour 2026_edited')
