insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2025-sept-17th-2025-rays-place-happy-hour', 'Sept. 17th 2025 Ray''s Place Happy Hour', 'On Sept. 17th, 2025 The Alumni Chapter headed down to Ray''s in Kent OH for our 3rd annual Ray''s Happy hour to help support the Kent State Chapter Recruitment. We got to meet with the Chapter, enjoy conversations with Actives, AMs and Potential New Members and enjoy the company of all the local Alumni.', 2025, 9, 17, 'f002fe_7e84149bb2cc40deb4e60494bf17f840-mv2.jpg', 'Ray''s Happy Hour 2025')
