insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2024-brewdog-doghouse-brotherhood-getaway', 'BrewDog Doghouse Brotherhood Getaway', 'On Nov. 9th nine chapter members traveled to southeast Columbus to the Brewdog Brewhouse hotel for an overnight brotherhood. We got 1 suite and a few rooms and all hanging out with each other building on our already shared Brotherhood. We played classic video games, had dinner and took part in all the brewery had to offer. It was a great event to build our group together.', 2024, 11, 9, 'f002fe_b0d728c2183c4de28437b69f2982a71e-mv2.jpeg', 'brewdog')
