insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2019-alumni-rededication-ceremony', 'Alumni Rededication Ceremony', 'The Alumni Chapter hosted two Alumni Rededication Ceremonies at both Kent State and Case Western for Graduating Seniors. We welcomed 6 Brothers to this further and continuation of our Ritual.', 2019, null, null, 'f002fe_17dc1bb5ae274ee89826f49087caa6c9-mv2.jpg', 'Alumni Ceremony2')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2019-feb-15-17-2019-region-vi-regional-leader-conference-rlc', 'Feb. 15 - 17, 2019: Region VI Regional Leader Conference (RLC)', 'The Northeast Ohio Alumni Chapter had the pleasure to host the 2019 Region VI RLC. The RLC was held at the Glenmoor Country Club in Canton, OH with a Brotherhood event at the Pro Football Hall of Fame. This is the first time Delta Chi History that an Alumni Chapters has hosted. See pictures in our [Photo Gallery.](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2019, 2, 15, 'f002fe_43c76dcde5f04c2184eb9140da5c5142-mv2.png', '')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2019-meet-and-greet-happy-hours', 'Meet and Greet Happy Hours', 'These were great events for Brothers to get together during the Holidays to hang out each other is a causal social event. See pictures in our [Photo Gallery.](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2019, null, null, 'f002fe_be656c70722b417f965c472c90f24ac4-mv2.jpg', 'happy hour')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2018-may-1-2018-indians-vs-texas-ranger', 'May 1, 2018: Indians vs Texas Ranger', 'The Northeast Ohio Alumni Chapter hosted it''s second Night with the Indians. This was a great event seeing Alumni and undergrads from all over Northeast Ohio. See pictures in our [photo gallery](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2018, 5, 1, 'f002fe_9f8d725c078f432890780a636125d8a8-mv2.png', '')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2017-october-13-2017-founders-day-dinner', 'October 13, 2017: Founder''s Day Dinner', 'Our 2nd annual Northeast Ohio all Chapter Founder Day Dinner. Sponsered by the Northeast Ohio Alumni Chapter, featuring the Case Western Chapter and Kent State Colony. This year''s event was at the Weymouth Country Club in Medina. See pictures in our [photo gallery](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2017, 10, 13, 'f002fe_17c8d73f2c97434fb80b08c51d1e2f7b-mv2.jpg', '')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2017-may-16-2017-a-night-at-the-ballpark', 'May 16, 2017: A night at the ballpark', 'The Northeast Ohio Alumni Chapter sponsored a night to see your 2016 American League Champion Cleveland Indians take on the Tampa Bay Rays at Progressive Field. The event saw Alumni from five different Chapters and their families, came out to meet and enjoy Brotherhood!! See pictures in our [photo gallery](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2017, 5, 16, 'f002fe_5a8dec596a4c4c38846734f13fb01134-mv2.jpg', '')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;
insert into public.events (slug, title, description, year, month, day, image_file, image_alt) values ('2016-october-13-2016-founders-day-dinner', 'October 13, 2016: Founder''s Day Dinner', 'The Northeast Ohio Alumni Chapter, co-sponsored with the Case Western Reserve Chapter a celebration of our Founder''s Day with a Dinner at Harry''s Steakhouse in Independence, OH. This event mark the reformation of the Northeast Ohio Alumni Chapter. See pictures in our [photo gallery](https://dxneoalumni.wixsite.com/main/photo-gallery)', 2016, 10, 13, 'f002fe_0c634f0595424520b5b294d64067f183-mv2.jpg', '')
on conflict (slug) do update set title = excluded.title, description = excluded.description, year = excluded.year, month = excluded.month, day = excluded.day, image_file = excluded.image_file, image_alt = excluded.image_alt;

